 }
 if(!body) throw new Error('未收到文档解析正文。请检查本节点text是否引用“文档解析→文档解析结果”，并查看该节点输出；这不代表未上传文件。');
 return {text:'【输入来源】HTML文件解析文本。仅依据可见正文；内嵌图片未经过OCR，不能推断图内数据。\n\n'+body};
